for await (const part of result.stream) {
  switch (part.type) {
    case 'text-delta':
      console.log('Text delta:', part.text);
      break;
    case 'tool-call':
      console.log('Tool call:', part.toolName, part.args);
      break;
    case 'tool-result':
      console.log('Tool result:', part.toolName, part.output);
      break;
    // handle other event types as needed
    default:
      console.log('Other event:', part.type);
  }
